def parse(self, source_code: bytes):
        """
        Parse Python source code and return the extracted file scope.
        """

        tree = self.parser.parse(source_code)

        return {
            "type": "file",
            "children": extract_scope(
                self,
                tree.root_node,
                source_code,
            ),
        }

