                    source_code,
                )
            )
            continue

if child.type == "while_statement":
            children.append(
                extract_while(
                    extractor,
                    child,
                    source_code,
                )
            )
            continue

if child.type == "try_statement":
            children.append(
                extract_try(
                    extractor,
                    child,
                    source_code,
                )
            )
            continue

if child.type in {
            "with_statement",
