        }:
            children.append(
                extract_with(
                    extractor,
                    child,
                    source_code,
                )
            )
            continue

if child.type == "match_statement":
            children.append(
                extract_match(
                    extractor,
                    child,
                    source_code,
                )
            )
            continue

if not child.children:
            children.append({
                "type": child.type,
                "start_line": child.start_point[0] + 1,
                "end_line": child.end_point[0] + 1,
                "unmatched" : True,
                "text": text(extractor, child, source_code),
            })
