def extract_decorated_definition(
    extractor,
    node,
    source_code,
):
    """
    Handles:

        @decorator
        def func():
            ...

    and:

        @decorator(...)
        class MyClass:
            ...
    """

    decorators = []
    definition = None

    for child in node.children:

        if child.type == "decorator":

            decorators.append({
                "type": "decorator",
                "text": text(
                    extractor,
                    child,
                    source_code,
                ),
                "start_line": child.start_point[0] + 1,
                "end_line": child.end_point[0] + 1,
            })

        elif child.type in {
            "function_definition",
            "async_function_definition",
            "class_definition",
        }:
            definition = child

    if definition is None:
        return None

    # ------------------------------------------------------------
    # Extract actual definition
    # ------------------------------------------------------------

    if definition.type in {
        "function_definition",
        "async_function_definition",
    }:
        result = extract_function(
            extractor,
            definition,
            source_code,
        )

    else:
        result = extract_class(
            extractor,
            definition,
            source_code,
        )

    # ------------------------------------------------------------
    # Attach decorators
    # ------------------------------------------------------------

    if decorators:
        result["decorators"] = decorators

    # The decorated definition starts at the first decorator.
    result["start_line"] = node.start_point[0] + 1
    result["end_line"] = node.end_point[0] + 1
    result["text"] = text(
        extractor,
        node,
        source_code,
    )

    return result

